@extends('layouts.app') @section('title','Receive '.$order->document_number) @section('content')
<div class="mb-4"><a href="{{ route('purchase-orders.show',$order) }}" class="text-decoration-none"><i class="bi bi-arrow-left"></i> {{ $order->document_number }}</a><h1 class="h3 page-title mt-2">Receive Goods</h1><p class="text-muted">Enter actual received quantities. Posting immediately updates stock and weighted-average cost.</p></div><form method="POST" action="{{ route('grn.store',$order) }}">@csrf<div class="card mb-4"><div class="card-body p-4"><div class="row g-3"><div class="col-md-3"><label class="form-label">Received date</label><input class="form-control" type="date" name="received_date" value="{{ old('received_date',date('Y-m-d')) }}" required></div><div class="col-md-4"><label class="form-label">Stock location</label><select class="form-select" name="stock_location_id" required>@foreach($locations as $l)<option value="{{ $l->id }}" @selected(old('stock_location_id',$l->is_default?$l->id:null)==$l->id)>{{ $l->code }} - {{ $l->name }}</option>@endforeach</select></div><div class="col-md-5"><label class="form-label">Supplier invoice number</label><input class="form-control" name="supplier_invoice_number" value="{{ old('supplier_invoice_number') }}"></div><div class="col-12"><label class="form-label">Notes</label><input class="form-control" name="notes" value="{{ old('notes') }}"></div></div></div></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th class="ps-4">Product</th><th>Remaining</th><th style="width:180px">Receive now</th><th style="width:460px">Serial capture</th></tr></thead><tbody>@foreach($order->items as $i)@php($remaining=$i->quantity-$i->received_quantity)@if($remaining>0)<tr class="serial-row"><td class="ps-4"><strong>{{ $i->product->name }}</strong><div class="small text-muted">Cost: Rs. {{ number_format($i->unit_cost,2) }}</div></td><td>@quantity($remaining)</td><td><input class="form-control receive-qty" type="number" step="0.0001" min="0" max="{{ $remaining }}" name="items[{{ $i->id }}][quantity]" value="{{ old('items.'.$i->id.'.quantity',0) }}"></td><td>@if($i->product->serial_tracking)<div class="input-group mb-2"><input class="form-control scan-input" placeholder="Scan serial, then press Enter"><button class="btn btn-outline-secondary add-scan" type="button">Add</button></div><textarea class="form-control serial-list" rows="3" name="items[{{ $i->id }}][serials]" placeholder="Scan or paste serials; comma/newline separated">{{ old('items.'.$i->id.'.serials') }}</textarea><div class="d-flex gap-2 mt-2"><input class="form-control form-control-sm serial-prefix" value="TEST-{{ $i->product->item_code }}-" aria-label="Prefix"><input class="form-control form-control-sm serial-start" type="number" value="1" min="0" aria-label="Starting number"><button class="btn btn-outline-primary btn-sm generate-serials" type="button">Generate range</button></div><small class="serial-count text-muted">0 serials captured</small>@else<span class="text-muted">Not serial tracked</span>@endif</td></tr>@endif @endforeach</tbody></table></div><div class="p-4 border-top"><button class="btn btn-success px-4" onclick="return confirm('Post this GRN and update stock?')"><i class="bi bi-check2-circle"></i> Post GRN</button></div></div></form>
@push('scripts')<script>document.querySelectorAll('.serial-row').forEach(row=>{const area=row.querySelector('.serial-list');if(!area)return;const qty=row.querySelector('.receive-qty'),scan=row.querySelector('.scan-input'),count=row.querySelector('.serial-count');const values=()=>area.value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);const update=()=>{const n=values().length;count.textContent=`${n} optional serial${n===1?'':'s'} captured${qty.value?` for ${qty.value} received`:''}`;count.className='serial-count '+(Number(qty.value)>0&&n>Number(qty.value)?'text-danger':'text-muted')};const add=()=>{const v=scan.value.trim();if(v&&!values().includes(v)){area.value+=(area.value.trim()?'\n':'')+v;scan.value='';update()}scan.focus()};row.querySelector('.add-scan').onclick=add;scan.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add()}});row.querySelector('.generate-serials').onclick=()=>{const n=Math.floor(Number(qty.value)),start=Number(row.querySelector('.serial-start').value),prefix=row.querySelector('.serial-prefix').value;if(n<1)return alert('Enter the received quantity first.');area.value=Array.from({length:n},(_,i)=>prefix+String(start+i).padStart(4,'0')).join('\n');update()};area.addEventListener('input',update);qty.addEventListener('input',update);update()});</script>@endpush
